:root {
  --white: #fbf7f1;
  --nude: #e8dcc5;
  --nude-soft: #f3ece0;
  --pink: #c9a876;
  --rose: #ad8567;
  --rose-deep: #8c6a50;
  --grey: #3d372f;
  --grey-soft: #8b8072;
  --line: #e3d8c4;
  padding-top: env(safe-area-inset-top, 0px);
  padding-bottom: env(safe-area-inset-bottom, 0px);
}
* {
  box-sizing: border-box;
  margin: 0;
  padding: 0;
}
html {
  scroll-behavior: smooth;
  scroll-padding-top: env(safe-area-inset-top, 0px);
}
body {
  background: var(--white);
  color: var(--grey);
  font-family: "Work Sans", sans-serif;
  font-size: 16px;
  line-height: 1.6;
  -webkit-font-smoothing: antialiased;
}
h1,
h2,
h3 {
  font-family: "Fraunces", serif;
  font-weight: 500;
  color: var(--grey);
  line-height: 1.15;
}
a {
  color: inherit;
  text-decoration: none;
}
img {
  max-width: 100%;
  display: block;
}
.wrap {
  max-width: 1120px;
  margin: 0 auto;
  padding: 0 32px;
}
.oflow {
  overflow-x: auto;
}

/* Header */
header {
  position: sticky;
  top: 0;
  z-index: 20;
  background: var(--nude-soft);
  border-bottom: 1px solid var(--line);
  padding-top: env(safe-area-inset-top, 0px);
}
nav.wrap {
  display: grid;
  grid-template-columns: 1fr auto 1fr;
  align-items: center;
  height: 88px;
}
.navlinks {
  display: flex;
  gap: 30px;
  font-size: 0.82rem;
  letter-spacing: 0.08em;
  text-transform: uppercase;
  color: var(--grey);
}
.navlinks a:hover {
  color: var(--rose-deep);
}
.nav-left {
  justify-self: start;
}
.nav-right {
  justify-self: end;
  align-items: center;
}
.logo {
  justify-self: center;
}
.monogram {
  font-family: "Fraunces", serif;
  font-size: 1.4rem;
  font-weight: 700;
  letter-spacing: 0.02em;
  color: var(--rose-deep);
  position: relative;
  padding-bottom: 5px;
  line-height: 1;
  white-space: nowrap;
}
.monogram::after,
.services h2::after {
  content: "";
  position: absolute;
  left: 4%;
  right: 4%;
  bottom: 0;
  height: 2px;
  background: var(--rose);
}
.navcta {
  margin-left: 8px;
}
.btn {
  display: inline-block;
  background: var(--rose);
  color: var(--white);
  padding: 12px 26px;
  font-size: 0.8rem;
  letter-spacing: 0.08em;
  text-transform: uppercase;
  font-weight: 500;
  transition: background 0.2s ease;
}
.btn:hover {
  background: var(--rose-deep);
}
.btn.ghost {
  background: transparent;
  border: 1px solid var(--white);
  color: var(--white);
}
.btn.ghost:hover {
  background: rgba(255, 255, 255, 0.12);
}
@media (max-width: 860px) {
  .navlinks {
    display: none;
  }
  nav.wrap {
    grid-template-columns: auto 1fr;
  }
}

/* Hero */
.hero {
  position: relative;
  min-height: 78vh;
  display: flex;
  align-items: center;
  justify-content: center;
  text-align: center;
  padding: 60px 24px;
  overflow: hidden;
  background:
    linear-gradient(180deg, rgba(40, 32, 22, 0.42), rgba(40, 32, 22, 0.5)),
    url("data:image/jpeg;base64,")
      center 65% / cover no-repeat;
}
.hero-inner {
  position: relative;
  z-index: 2;
  max-width: 820px;
}
.hero .kicker {
  color: var(--nude);
  letter-spacing: 0.14em;
  text-transform: uppercase;
  font-size: 0.8rem;
  margin-bottom: 18px;
}
.hero h1 {
  color: var(--white);
  font-size: clamp(2.6rem, 6vw, 4.4rem);
  letter-spacing: 0.02em;
}
.hero p.lead {
  margin-top: 22px;
  color: var(--nude-soft);
  font-size: 1rem;
  letter-spacing: 0.1em;
  text-transform: uppercase;
}
.hero .ctas {
  margin-top: 38px;
}
@media (max-width: 760px) {
  .hero {
    min-height: 64vh;
    padding: 52px 20px;
  }
}

/* Section shell */
section {
  padding: 88px 0;
}
.eyebrow {
  font-size: 0.95rem;
  color: var(--rose-deep);
  font-family: "Fraunces", serif;
  font-weight: 500;
  margin-bottom: 10px;
}
section h2 {
  font-size: clamp(1.8rem, 3.4vw, 2.4rem);
  max-width: 16ch;
  margin-bottom: 14px;
}
section p.intro {
  color: var(--grey-soft);
  max-width: 52ch;
  margin-bottom: 44px;
}
.divider {
  height: 1px;
  background: var(--line);
  border: none;
}

/* Services */
.services {
  --grey: #3d372f;
  --grey-soft: #51483e;
  --line: #cbbba5;
  padding: 50px 0;
  /* Reserve the lower-right product area so it never sits behind copy. */
  padding-bottom: max(140px, 32vw);
  position: relative;
  isolation: isolate;
  background: #e3d7c9;
}
.services::before {
  content: "";
  position: absolute;
  bottom: 0;
  left: 0;
  width: 100%;
  aspect-ratio: 3 / 2;
  z-index: -1;
  pointer-events: none;
  background:
    linear-gradient(rgba(251, 247, 241, 0.3), rgba(251, 247, 241, 0.3)),
    url("assets/white-cleaning-products-v3.png") center / cover no-repeat;
  /* Hide the photo's wall behind the copy, preserving the products below. */
  -webkit-mask-image: linear-gradient(to bottom, transparent 48%, #000 56%);
  mask-image: linear-gradient(to bottom, transparent 48%, #000 56%);
}
.services h2 {
  color: var(--rose-deep);
  position: relative;
  width: fit-content;
  padding-bottom: 5px;
}
.services h2::after {
  left: 0;
  right: 0;
}
@media (min-width: 701px) {
  .services h2 {
    margin-bottom: 44px;
  }
}
.service-row {
  display: grid;
  grid-template-columns: 1fr 1.6fr;
  gap: 36px;
  padding: 34px 0;
  border-bottom: 1px solid var(--line);
}
.services h3 {
  font-size: 1.4rem;
}
.service-row p {
  color: #241b14;
  max-width: 48ch;
}
.service-font {
  font-size: 20px;
}

@media (max-width: 700px) {
  .service-row {
    grid-template-columns: 1fr;
  }

  .service-font {
    font-size: 16px;
  }
}

/* About */
.about-top {
  display: grid;
  grid-template-columns: 1fr 1.3fr;
  gap: 48px;
  align-items: stretch;
  margin-bottom: 80px;
}
.about-photo {
  background:
    url("data:image/png;base64,")
      center 20% / cover no-repeat,
    var(--nude-soft);
  display: flex;
  align-items: flex-end;
  justify-content: center;
  text-align: center;
  color: var(--grey-soft);
  font-size: 0.9rem;
  padding: 20px;
}
.about-copy h2 {
  margin-bottom: 18px;
}
.about-me p {
  font-size: 1.08rem;
  color: var(--grey);
  margin-bottom: 16px;
}
@media (max-width: 760px) {
  .about-top {
    grid-template-columns: 1fr;
    gap: 28px;
  }
  .about-photo {
    width: 100%;
    /* Keep the tighter desktop-style crop on smaller screens. */
    aspect-ratio: 1 / 1;
    margin: 0 auto;
  }

  @media (max-width: 768px) {
    .about-image {
      width: 100%;
      max-width: 350px;
      height: auto;
      display: block;
      margin: 0 auto;
    }
  }
}
.about-grid {
  display: grid;
  grid-template-columns: repeat(2, 1fr);
  gap: 40px;
}
.person {
  background: var(--nude-soft);
  border-radius: 20px;
  padding: 32px;
}
.avatar {
  width: 64px;
  height: 64px;
  border-radius: 50%;
  background: var(--rose);
  color: var(--white);
  display: flex;
  align-items: center;
  justify-content: center;
  font-family: "Fraunces", serif;
  font-size: 1.4rem;
  margin-bottom: 18px;
}
.person h3 {
  font-size: 1.25rem;
  margin-bottom: 4px;
}
.person .role {
  color: var(--rose-deep);
  font-size: 0.9rem;
  margin-bottom: 14px;
}
.person p.bio {
  color: var(--grey-soft);
  font-size: 0.96rem;
}
@media (max-width: 700px) {
  .about-grid {
    grid-template-columns: 1fr;
  }
}

/* Why us */
.why {
  background: var(--nude-soft);
  border-radius: 28px;
  padding: 56px 48px;
}
.why h2 {
  font-weight: 700;
  color: var(--rose-deep);
  margin-bottom: 28px;
}
.why-grid {
  display: grid;
  grid-template-columns: repeat(2, 1fr);
  gap: 16px 40px;
}
.why-item {
  display: flex;
  gap: 12px;
  align-items: flex-start;
  padding: 10px 0;
}
.check {
  color: var(--rose-deep);
  font-weight: 600;
  font-size: 1.1rem;
  line-height: 1.5;
}
@media (max-width: 700px) {
  .why {
    padding: 40px 26px;
  }
  .why-grid {
    grid-template-columns: 1fr;
  }
}

/* Testimonials */
.title {
  font-family: "Fraunces", serif;
  font-weight: 500;
  color: #ad8567;
  line-height: 1.15;
}

.quotes {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 32px;
}
blockquote {
  font-family: "Fraunces", serif;
  font-style: italic;
  font-size: 1.15rem;
  color: var(--grey);
  line-height: 1.5;
}
cite {
  display: block;
  margin-top: 16px;
  font-family: "Work Sans";
  font-style: normal;
  font-size: 0.88rem;
  color: var(--grey-soft);
}
@media (max-width: 800px) {
  .quotes {
    grid-template-columns: 1fr;
    gap: 40px;
  }
}

/* Contact / footer */
footer {
  background: var(--nude-soft);
  color: var(--nude-soft);
  padding: 72px 0 40px;
}
.foot-grid {
  display: grid;
  grid-template-columns: 1.3fr 1fr 1fr;
  gap: 40px;
  padding-bottom: 44px;
  border-bottom: 1px solid #8c6a50;
}
footer h2 {
  color: #8c6a50;
  font-size: 2rem;
  max-width: 12ch;
}
footer .foot-lead {
  color: black;
  margin-top: 14px;
  max-width: 36ch;
}
footer .btn {
  margin-top: 26px;
}
footer h4 {
  font-family: "Work Sans";
  font-size: 0.85rem;
  text-transform: none;
  color: #cbb9ae;
  margin-bottom: 14px;
}
footer .foot-col a,
footer .foot-col p {
  display: block;
  margin-bottom: 9px;
  font-size: 0.95rem;
  color: black;
}
footer .foot-col a:hover {
  color: var(--pink);
}
.fine {
  padding-top: 26px;
  font-size: 0.82rem;
  color: #a6968b;
  display: flex;
  justify-content: space-between;
  flex-wrap: wrap;
  gap: 8px;
}
@media (max-width: 760px) {
  .foot-grid {
    grid-template-columns: 1fr;
  }
}

@media (prefers-color-scheme: dark) {
  :root:not([data-theme="light"]) {
    --white: #211e1c;
    --nude-soft: #2c2723;
    --nude: #3a3129;
    --grey: #f1e9e3;
    --grey-soft: #b7aca4;
    --line: #3a332d;
  }
  body {
    background: var(--white);
    color: var(--grey);
  }
  header {
    background: var(--nude-soft);
  }
}
:root[data-theme="light"] {
  --white: #211e1c;
  --nude-soft: #2c2723;
  --nude: #3a3129;
  --grey: #f1e9e3;
  --grey-soft: #b7aca4;
  --line: #3a332d;
}
